const express=require('express'),router=express.Router(),upload=require('../utilities/multer'),cloudinary=require('../utilities/cloudinary'),tinify=require('tinify');require('dotenv').config(),tinify.key=process.env.TINIFY_KEY;const compressImage=(e,r,t)=>{tinify.fromFile(e.file.path).toFile(e.file.path,()=>t())};router.post('/single',upload.single('image'),compressImage,async(e,r)=>{if(!e.file)return r.send({code:422,msg:'field_required'});const t=await cloudinary.uploader.upload(e.file.path);r.status(200).send(t)}),router.post('/video',upload.single('file'),async(e,r)=>{if(!e.file)return r.status(422).send({code:422,msg:'field_required'});try{const t=await cloudinary.uploader.upload(e.file.path,{resource_type:'video'});r.status(200).send(t)}catch(e){r.status(500).send({code:500,msg:'upload_error',error:e.message})}});module.exports=router; 